import AVFoundation
import AppKit
import CoreImage

/// Diagnostic only: distinguish source random access from compositor captures.
/// Use the barcode fixture generated by system-sequence-matrix.py --include-open-gop.
@main struct SystemOpenGOPDiagnostic {
    static func barcode(_ image: CGImage) -> [Int] {
        var pixels = [UInt8](repeating: 0, count: 128 * 64 * 4)
        pixels.withUnsafeMutableBytes { bytes in
            let context = CGContext(data: bytes.baseAddress, width: 128, height: 64,
                bitsPerComponent: 8, bytesPerRow: 128 * 4, space: CGColorSpaceCreateDeviceRGB(),
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
            context.draw(image, in: CGRect(x: 0, y: 0, width: 128, height: 64))
        }
        return (0..<8).map { Int(pixels[(32 * 128 + $0 * 16 + 8) * 4]) }
    }

    static func main() async throws {
        guard CommandLine.arguments.count == 4,
              let numerator = Int32(CommandLine.arguments[2]),
              let denominator = Int64(CommandLine.arguments[3]), numerator > 0, denominator > 0 else {
            print("Usage: diagnostic barcode.mov frame-rate-numerator frame-rate-denominator")
            exit(2)
        }
        let url = URL(fileURLWithPath: CommandLine.arguments[1])
        let asset = AVURLAsset(url: url)
        let source = try await asset.loadTracks(withMediaType: .video)[0]
        func time(_ frame: Int64) -> CMTime { CMTime(value: frame * denominator, timescale: numerator) }
        let composition = AVMutableComposition()
        let track = composition.addMutableTrack(withMediaType: .video, preferredTrackID: kCMPersistentTrackID_Invalid)!
        // An untrimmed track isolates random access from clip-boundary dependencies.
        try track.insertTimeRange(CMTimeRange(start: .zero, duration: time(96)), of: source, at: .zero)
        let video = AVMutableVideoComposition()
        video.renderSize = CGSize(width: 128, height: 64)
        video.frameDuration = time(1)
        let instruction = AVMutableVideoCompositionInstruction()
        instruction.timeRange = CMTimeRange(start: .zero, duration: time(96))
        instruction.backgroundColor = NSColor.black.cgColor
        instruction.layerInstructions = [AVMutableVideoCompositionLayerInstruction(assetTrack: track)]
        video.instructions = [instruction]
        var observations: [[String: Any]] = []
        for frame: Int64 in [60, 70] {
            for mode in ["source-generator", "composition-generator", "reader-exact", "reader-24-frame-preroll", "reader-from-zero", "player-seek-output"] {
                var observation: [String: Any] = ["sourceFrame": frame, "mode": mode]
                do {
                    let image: CGImage
                    let actual: CMTime
                    if mode.hasSuffix("generator") {
                        let generator = AVAssetImageGenerator(asset: mode == "source-generator" ? asset : composition)
                        if mode == "composition-generator" { generator.videoComposition = video }
                        generator.requestedTimeToleranceBefore = .zero
                        generator.requestedTimeToleranceAfter = .zero
                        var generatedTime = CMTime.invalid
                        image = try generator.copyCGImage(at: time(frame), actualTime: &generatedTime)
                        actual = generatedTime
                    } else if mode == "player-seek-output" {
                        let item = AVPlayerItem(asset: composition)
                        item.videoComposition = video
                        let output = AVPlayerItemVideoOutput(pixelBufferAttributes:
                            [kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_32BGRA])
                        item.add(output)
                        let player = AVPlayer(playerItem: item)
                        guard await player.seek(to: time(frame), toleranceBefore: .zero, toleranceAfter: .zero) else {
                            throw NSError(domain: "Diagnostic", code: 2,
                                userInfo: [NSLocalizedDescriptionKey: "Player seek cancelled"])
                        }
                        var selected: CVPixelBuffer?
                        var displayed = CMTime.invalid
                        for _ in 0..<25 {
                            try await Task.sleep(for: .milliseconds(20))
                            selected = output.copyPixelBuffer(forItemTime: time(frame), itemTimeForDisplay: &displayed)
                            if selected != nil { break }
                        }
                        player.replaceCurrentItem(with: nil)
                        guard let selected else {
                            throw item.error ?? NSError(domain: "Diagnostic", code: 3,
                                userInfo: [NSLocalizedDescriptionKey: "No paused player output within 500 ms"])
                        }
                        actual = displayed
                        let ci = CIImage(cvPixelBuffer: selected)
                        image = CIContext().createCGImage(ci, from: ci.extent)!
                    } else {
                        let reader = try AVAssetReader(asset: composition)
                        let output = AVAssetReaderVideoCompositionOutput(videoTracks: [track], videoSettings:
                            [kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_32BGRA])
                        output.videoComposition = video
                        reader.add(output)
                        let start = mode == "reader-from-zero" ? 0 : (mode == "reader-exact" ? frame : max(0, frame - 24))
                        reader.timeRange = CMTimeRange(start: time(start), duration: time(frame + 1 - start))
                        guard reader.startReading() else { throw reader.error! }
                        defer { reader.cancelReading() }
                        var selected: CMSampleBuffer?
                        // Fixed synthetic 96-frame fixture, bounded independently of media duration.
                        for _ in 0..<97 {
                            guard let sample = output.copyNextSampleBuffer() else { break }
                            if CMTimeCompare(CMSampleBufferGetPresentationTimeStamp(sample), time(frame)) >= 0 {
                                selected = sample; break
                            }
                        }
                        guard let selected, let buffer = CMSampleBufferGetImageBuffer(selected) else {
                            throw reader.error ?? NSError(domain: "Diagnostic", code: 1,
                                userInfo: [NSLocalizedDescriptionKey: "No requested sample"])
                        }
                        actual = CMSampleBufferGetPresentationTimeStamp(selected)
                        let ci = CIImage(cvPixelBuffer: buffer)
                        image = CIContext().createCGImage(ci, from: ci.extent)!
                    }
                    let stripes = barcode(image)
                    let expected = (0..<8).map { frame & (1 << $0) == 0 ? 32 : 224 }
                    observation["stripes"] = stripes
                    observation["actualTimeSeconds"] = actual.seconds
                    observation["passed"] = CMTimeCompare(actual, time(frame)) == 0 &&
                        zip(stripes, expected).allSatisfy { abs($0 - $1) <= 24 }
                } catch {
                    observation["passed"] = false
                    observation["error"] = String(describing: error)
                }
                observations.append(observation)
            }
        }
        let data = try JSONSerialization.data(withJSONObject: ["fixture": url.lastPathComponent,
            "frameRate": "\(numerator)/\(denominator)", "observations": observations], options: [.prettyPrinted, .sortedKeys])
        print(String(decoding: data, as: UTF8.self))
    }
}
